// Alert spine: every workflow and every external alert source posts here, and
// this decides whether it is worth interrupting a human for.
//
// The point is not formatting -- it is suppression. An alert that repeats every
// five minutes trains you to ignore the channel, so the same fingerprint is
// held down for a severity-dependent window and a repeat only escapes when it
// escalates. State lives in workflow static data because that is the only
// store a Code node gets; it is a cache, not a ledger, so losing it on a
// restart costs at most one duplicate notification.

const SEVERITY = {
  critical: { priority: 5, tag: "rotating_light", window: 30 * 60 * 1000 },
  warning: { priority: 4, tag: "warning", window: 24 * 60 * 60 * 1000 },
  info: { priority: 3, tag: "information_source", window: 24 * 60 * 60 * 1000 },
};
const RANK = { info: 0, warning: 1, critical: 2 };

// Warning sits at a day rather than the four hours it started with. The
// alerts that actually persist here are absences -- a laptop that is off, a
// monthly drill that has not come round yet -- and at four hours three of
// those produced eighteen pushes a day between them, which is the behaviour
// this workflow exists to prevent. Critical stays at half an hour: something
// that wants an action tonight should keep asking.

// Unknown severities are rejected rather than coerced: a typo silently
// downgraded to "info" is an alert that never pages, which is the exact
// failure this workflow exists to prevent.
function normalise(raw) {
  const severity = String(raw.severity ?? "warning").toLowerCase();
  if (!SEVERITY[severity]) {
    throw new Error(
      `unknown severity ${JSON.stringify(raw.severity)}; expected one of ${Object.keys(SEVERITY).join(", ")}`,
    );
  }
  const source = String(raw.source ?? "unknown").trim();
  const title = String(raw.title ?? "").trim();
  if (!title) throw new Error("alert has no title");

  return {
    source,
    severity,
    title,
    message: String(raw.message ?? "").trim(),
    // Callers that omit a fingerprint get one that is stable for the same
    // source and headline, which is the behaviour they almost certainly want.
    fingerprint: String(raw.fingerprint ?? `${source}:${title}`),
    resolved: raw.resolved === true || raw.resolved === "true",
    url: raw.url ? String(raw.url) : null,
    extraTags: Array.isArray(raw.tags) ? raw.tags.map(String) : [],
  };
}

function decide(alert, state, now) {
  const seen = state[alert.fingerprint];

  if (alert.resolved) {
    if (!seen) return { send: false, reason: "resolved, but nothing was open" };
    delete state[alert.fingerprint];
    return { send: true, reason: "resolved", resolution: true };
  }

  if (!seen) return { send: true, reason: "first occurrence" };

  // An escalation is news even inside the suppression window; a de-escalation
  // is not, or a flapping service would page on every recovery.
  if (RANK[alert.severity] > RANK[seen.severity]) {
    return { send: true, reason: `escalated from ${seen.severity}` };
  }

  const age = now - seen.lastSent;
  const window = SEVERITY[alert.severity].window;
  if (age >= window) {
    return { send: true, reason: `still open after ${Math.round(age / 60000)}m` };
  }

  return {
    send: false,
    reason: `suppressed, ${Math.round((window - age) / 60000)}m of window left`,
  };
}

function render(alert, decision, seen) {
  const spec = SEVERITY[alert.severity];
  const count = (seen?.count ?? 0) + 1;

  // ntfy renders the tag names as emoji, but the title carries the state in
  // words too: the same rule the email digests follow, so a notification is
  // still readable when tags are stripped or the reader is colour-blind.
  const prefix = decision.resolution
    ? "[OK]"
    : { critical: "[CRIT]", warning: "[WARN]", info: "[INFO]" }[alert.severity];

  const lines = [alert.message];
  if (!decision.resolution && count > 1) lines.push(`Seen ${count}x; ${decision.reason}.`);
  if (alert.url) lines.push(alert.url);

  return {
    topic: $env.NTFY_TOPIC,
    title: `${prefix} ${alert.source} · ${alert.title}`,
    message: lines.filter(Boolean).join("\n\n") || alert.title,
    priority: decision.resolution ? 3 : spec.priority,
    tags: decision.resolution
      ? ["white_check_mark"]
      : [spec.tag, ...alert.extraTags],
    ...(alert.url ? { click: alert.url } : {}),
  };
}

const state = $getWorkflowStaticData("global");
if (!state.alerts) state.alerts = {};
const now = Date.now();

// Fingerprints that have been quiet for a week are dropped, so a workflow that
// invents a new fingerprint per run cannot grow this object without bound.
for (const [key, entry] of Object.entries(state.alerts)) {
  if (now - entry.lastSent > 7 * 24 * 60 * 60 * 1000) delete state.alerts[key];
}

const out = [];
for (const item of $input.all()) {
  const raw = item.json.body ?? item.json;
  let alert;
  try {
    alert = normalise(raw);
  } catch (error) {
    // A malformed alert is itself worth knowing about, and dropping it
    // silently would hide whichever workflow is sending nonsense.
    out.push({
      json: {
        send: true,
        reason: "malformed alert",
        payload: {
          topic: $env.NTFY_TOPIC,
          title: "[WARN] alert-router · malformed alert",
          message: `${error.message}\n\n${JSON.stringify(raw).slice(0, 400)}`,
          priority: 4,
          tags: ["warning"],
        },
      },
    });
    continue;
  }

  const seen = state.alerts[alert.fingerprint];
  const decision = decide(alert, state.alerts, now);
  const payload = decision.send ? render(alert, decision, seen) : null;

  if (decision.send && !decision.resolution) {
    state.alerts[alert.fingerprint] = {
      lastSent: now,
      severity: alert.severity,
      count: (seen?.count ?? 0) + 1,
      title: alert.title,
    };
  }

  out.push({
    json: { send: decision.send, reason: decision.reason, fingerprint: alert.fingerprint, payload },
  });
}

return out;
